import type { AgentClient } from '../../api/agent-clients.ts';

/**
 * Each coding agent's real brand mark, as SVG path data (LAI-740, on the
 * owner's direct instruction — it reverses LAI-737's monogram-only choice;
 * `NOTICE.md` beside this file records both).
 *
 * **Vendored, never fetched.** Every path below was downloaded once with
 * `curl` from the source named on its entry, and is checked in: no npm
 * dependency, no request to any other origin at run time (SPEC §13.4, and the
 * CSP's `img-src`/`connect-src 'self'`). `agent-logos.test.ts` asserts that no
 * entry carries a URL anywhere it could be drawn.
 *
 * **The colours are the brand's, not the theme's**, which is why this is the
 * one other file `theme-single-source.test.ts` lets hold a colour literal: a
 * vendor's mark has exactly one right colour, and no theme can reach it. The
 * tile the mark sits on is a theme token (`--logo-tile`), light in both
 * themes, so every mark keeps its own contrast; a single-colour mark that the
 * set ships in `currentColor` is drawn in `--logo-ink` (`paint: 'ink'`).
 *
 * Cleaning was limited to what a 34px tile cannot show: Visual Studio Code's
 * two drop-shadow filters and its 25% blend overlay, and Continue's
 * full-frame clip path. Path data is copied exactly.
 *
 * `other` has no mark — it is *another agent*, not a brand — and keeps its
 * monogram.
 */

export type LogoPaint = 'ink' | `#${string}` | { readonly gradient: string };

export interface LogoShape {
  readonly d: string;
  readonly paint: LogoPaint;
  readonly fillRule?: 'evenodd';
  readonly opacity?: number;
  /** Drawn inside the entry's `mask`. */
  readonly masked?: boolean;
}

export interface LogoGradient {
  readonly id: string;
  readonly x1: number;
  readonly y1: number;
  readonly x2: number;
  readonly y2: number;
  readonly stops: readonly { readonly offset: number; readonly color: string }[];
}

export interface AgentLogo {
  /** Whose mark it is, for the provenance record — never rendered. */
  readonly brand: string;
  readonly viewBox: string;
  /** Exactly where the SVG was downloaded from. */
  readonly source: string;
  readonly licence: string;
  readonly mask?: { readonly d: string; readonly fillRule?: 'evenodd' };
  readonly gradients?: readonly LogoGradient[];
  readonly shapes: readonly LogoShape[];
}

